CREATE OR REPLACE FUNCTION sync_user_deleted_status()
RETURNS TRIGGER AS $$
BEGIN
    IF (OLD.deleted IS DISTINCT FROM NEW.deleted) THEN
        UPDATE patients SET deleted = NEW.deleted WHERE user_id = NEW.user_id;
        UPDATE doctors SET deleted = NEW.deleted WHERE user_id = NEW.user_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_sync_user_deleted
AFTER UPDATE OF deleted ON users
FOR EACH ROW
EXECUTE FUNCTION sync_user_deleted_status();
